mapper.select:
select con.*, wk.id 'workshopId', wk.name 'workshopName', pro.id 'processId', pro.name 'processName', pro.product_type 'process.productType' from mes_inspect_config con left join mes_building_workshop wk on con.workshop_id = wk.id and wk.bool_delete_enum = 0 left join mes_building_process pro on con.process_id = pro.id and pro.bool_delete_enum = 0 where con.bool_delete_enum = 0
and con.workshop_id = #{workshopId}
and con.process_id = #{processId}
and con.status = #{status}
and con.mes_product_enum = #{mesProductEnum}

select con.*
from mes_inspect_config con
left join mes_inspect_config_user_link cul on con.id = cul.inspect_config_id and cul.bool_delete_enum = 0
left join mes_inspect_config_team_link tl on con.id = tl.inspect_config_id and tl.bool_delete_enum = 0
where con.bool_delete_enum = 0
and con.process_id = #{processId}


    and  con.artifact_type = #{artifactType}


    and con.id != #{id}


    and con.mes_product_enum = #{mesProductEnum}

and cul.inspect_user_id in

    #{userId}

and tl.team_id in

    #{team}

select con.*
from mes_inspect_config con
         left join mes_inspect_config_team_link teamLink on con.id = teamLink.inspect_config_id and teamLink.bool_delete_enum = 0
         left join mes_inspect_classification_config_link classLink on con.id = classLink.inspect_config_id  and classLink.bool_delete_enum = 0
where con.bool_delete_enum = 0
and con.workshop_id = #{config.workshopId}
and con.task_type_enum = #{config.taskTypeEnum}
and con.process_id = #{config.processId}
and teamLink.team_id = #{teamId}
and classLink.classification_id  = #{classId}
